{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is missing a Public Access block, which could lead to unintended public access if other configurations are changed."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have access logging enabled, making it difficult to track and monitor access to the bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"b\" {\n  bucket = \"my-tf-test-bucket-ggff\"\n  acl    = \"private\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"b\" {\n  bucket = aws_s3_bucket.b.id\n\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_logging\" \"b\" {\n  bucket = aws_s3_bucket.b.id\n\n  target_bucket = \"${aws_s3_bucket.b.id}-logs\"\n  target_prefix = \"log/\"\n}",
  "fix_summary": "Added a Public Access block to the S3 bucket and enabled access logging by creating an S3 bucket logging resource."
}
